<?php

declare(strict_types=1);

const BASELINE = '3f1a8e319cbfac36de2eb21aec100d6d9ad37006';
const EXPECTED_BRANCH = 'feat/group-spaces-communication';

$files = json_decode(base64_decode(''), true, flags: JSON_THROW_ON_ERROR);
$expectedHashes = json_decode(base64_decode(''), true, flags: JSON_THROW_ON_ERROR);
$localeBlocks = json_decode(base64_decode(''), true, flags: JSON_THROW_ON_ERROR);

function failApply(string $message): never
{
    fwrite(STDERR, "ERROR: {$message}".PHP_EOL);
    exit(1);
}

/** @return array{int, string} */
function runCommand(array $arguments, bool $allowFailure = false): array
{
    $command = implode(' ', array_map('escapeshellarg', $arguments));
    $output = [];
    $code = 0;
    exec($command.' 2>&1', $output, $code);
    $text = trim(implode(PHP_EOL, $output));
    if (! $allowFailure && $code !== 0) {
        failApply("Command failed: {$command}".($text !== '' ? PHP_EOL.$text : ''));
    }

    return [$code, $text];
}

[, $root] = runCommand(['git', 'rev-parse', '--show-toplevel']);
$root = rtrim($root, "\/");
[, $branch] = runCommand(['git', '-C', $root, 'branch', '--show-current']);
if ($branch !== EXPECTED_BRANCH) {
    failApply('Expected branch '.EXPECTED_BRANCH.", got [{$branch}]. Nothing was modified.");
}
[, $head] = runCommand(['git', '-C', $root, 'rev-parse', 'HEAD']);
if ($head !== BASELINE) {
    failApply('Expected local HEAD '.BASELINE.", got {$head}. Phase 2.2 is expected to remain uncommitted. Nothing was modified.");
}

// Phase 2.2 is intentionally local/uncommitted. Verify only the exact target files
// that Phase 2.3A will modify; unrelated working-tree changes are preserved.
foreach ($expectedHashes as $path => $expectedHash) {
    $destination = $root.DIRECTORY_SEPARATOR.str_replace('/', DIRECTORY_SEPARATOR, $path);
    if (! is_file($destination)) {
        failApply("Expected Phase 2.2 target is missing: {$path}. Nothing was modified.");
    }
    $actualHash = hash_file('sha256', $destination);
    if ($actualHash !== $expectedHash) {
        failApply("Phase 2.2 target mismatch for {$path}. Expected sha256 {$expectedHash}, got {$actualHash}. Nothing was modified.");
    }
}

$newPaths = array_values(array_diff(array_keys($files), array_keys($expectedHashes)));
foreach ($newPaths as $path) {
    $destination = $root.DIRECTORY_SEPARATOR.str_replace('/', DIRECTORY_SEPARATOR, $path);
    if (file_exists($destination)) {
        failApply("New Phase 2.3A path already exists: {$path}. Nothing was modified.");
    }
}

$localeFinal = [];
foreach ($localeBlocks as $locale => $block) {
    $path = $root.DIRECTORY_SEPARATOR.'lang'.DIRECTORY_SEPARATOR.$locale.DIRECTORY_SEPARATOR.'ui.php';
    $text = file_get_contents($path);
    if ($text === false) {
        failApply("Could not read {$path}. Nothing was modified.");
    }
    if (! str_contains($text, "    'spaces' => [")) {
        failApply("Phase 2.2 spaces localization is missing in {$path}. Nothing was modified.");
    }
    if (! str_contains($text, "        'manage_spaces' =>")) {
        failApply("Phase 2.2 manage_spaces localization is missing in {$path}. Nothing was modified.");
    }
    if (str_contains($text, "    'content' => [")) {
        failApply("A Content localization block already exists in {$path}. Nothing was modified.");
    }
    $marker = "    'permissions' => [
";
    if (substr_count($text, $marker) !== 1) {
        failApply("Could not locate a unique permissions localization section in {$path}. Nothing was modified.");
    }
    $localeFinal[$path] = str_replace($marker, $block.$marker, $text);
}

$originals = [];
$created = [];
try {
    foreach ($files as $path => $content) {
        $destination = $root.DIRECTORY_SEPARATOR.str_replace('/', DIRECTORY_SEPARATOR, $path);
        $directory = dirname($destination);
        if (! is_dir($directory) && ! mkdir($directory, 0777, true) && ! is_dir($directory)) {
            throw new RuntimeException("Could not create directory {$directory}.");
        }
        if (is_file($destination)) {
            $originals[$destination] = file_get_contents($destination);
        } else {
            $created[] = $destination;
        }
        if (file_put_contents($destination, $content) === false) {
            throw new RuntimeException("Could not write {$path}.");
        }
    }

    foreach ($localeFinal as $path => $content) {
        $originals[$path] = file_get_contents($path);
        if (file_put_contents($path, $content) === false) {
            throw new RuntimeException("Could not update {$path}.");
        }
    }
} catch (Throwable $exception) {
    foreach ($originals as $path => $content) {
        if (is_string($content)) {
            @file_put_contents($path, $content);
        }
    }
    foreach ($created as $path) {
        @unlink($path);
    }
    failApply($exception->getMessage().' Applied writes were rolled back where possible.');
}

echo 'Phase 2.3A Space Content Definition MVP applied to the working tree.'.PHP_EOL;
echo 'Existing uncommitted Phase 2.2 work was preserved; no Git staging, commit, reset, checkout, pull, or push was performed.'.PHP_EOL.PHP_EOL;
echo 'Review:'.PHP_EOL;
echo '  git status --short'.PHP_EOL;
echo '  git diff --stat'.PHP_EOL;
echo '  git diff --check'.PHP_EOL.PHP_EOL;
echo 'Next narrow validation:'.PHP_EOL;
echo '  php artisan migrate'.PHP_EOL;
echo '  php artisan test --compact tests/Feature/Groups/SpaceContentDefinitionTest.php'.PHP_EOL;
echo '  php artisan test --compact tests/Feature/Groups/SpaceContentRevisionConcurrencyTest.php'.PHP_EOL;
